INSERT INTO daily_tips (category, content_en, content_es, tip_order) VALUES
('fold_cleaning', 'Clean your Frenchie''s facial folds daily with a soft, damp cloth. Moisture trapped in folds can lead to yeast and bacterial infections within 24–48 hours.', 'Limpia los pliegues faciales de tu Frenchie diariamente con un paño suave y húmedo. La humedad atrapada en los pliegues puede causar infecciones por hongos o bacterias en 24–48 horas.', 1),
('fold_cleaning', 'After cleaning folds, dry them thoroughly — a damp fold is a breeding ground for bacteria. Use a dry cotton round to absorb remaining moisture.', 'Después de limpiar los pliegues, sécalos completamente. Un pliegue húmedo es un caldo de cultivo para bacterias. Usa un algodón seco para absorber la humedad restante.', 2),
('fold_cleaning', 'Use fragrance-free, alcohol-free wipes for daily fold maintenance. Fragranced products disrupt your Frenchie''s skin microbiome and can trigger irritation.', 'Usa toallitas sin fragancia ni alcohol para el mantenimiento diario de los pliegues. Los productos perfumados alteran el microbioma de la piel y pueden causar irritación.', 3),
('fold_cleaning', 'Inspect the nose rope (the fold above the nose) weekly for redness or odor. This is one of the first spots to develop skin fold dermatitis in French Bulldogs.', 'Inspecciona el pliegue sobre la nariz semanalmente en busca de enrojecimiento u olor. Es uno de los primeros puntos en desarrollar dermatitis por pliegues en Bulldogs Franceses.', 4),
('fold_cleaning', 'Apply a thin layer of dog-safe cornstarch or medicated powder (only after vet guidance) to keep deep folds dry between cleanings.', 'Aplica una capa delgada de almidón de maíz apto para perros o polvo medicado (solo bajo indicación veterinaria) para mantener los pliegues secos entre limpiezas.', 5),
('fold_cleaning', 'Tail pockets — the fold around your Frenchie''s corkscrew tail — need the same daily cleaning as facial folds. Many owners forget this area until infection sets in.', 'El "bolsillo de la cola" — el pliegue alrededor de la cola de tirabuzón — necesita la misma limpieza diaria que los pliegues faciales. Muchos dueños olvidan esta zona hasta que aparece la infección.', 6),
('fold_cleaning', 'After meals, wipe food residue from facial folds immediately. Wet food left in folds ferments rapidly and causes odor and infection.', 'Después de las comidas, limpia los residuos de comida de los pliegues faciales de inmediato. El alimento húmedo que queda en los pliegues fermenta rápidamente y causa mal olor e infección.', 7),
('nutrition', 'Chicken is the #1 most common food allergen in French Bulldogs. If your dog has chronic itching, try a chicken-free diet for 8–12 weeks before concluding "it''s environmental."', 'El pollo es el alérgeno alimentario #1 más común en Bulldogs Franceses. Si tu perro tiene picazón crónica, prueba una dieta sin pollo durante 8–12 semanas antes de concluir que "es ambiental".', 8),
('nutrition', 'Beef is the second most common food allergen in Frenchies. An elimination diet works best when you switch to a novel protein your dog has never eaten — duck, venison, or kangaroo.', 'La carne de res es el segundo alérgeno alimentario más común en Frenchies. Una dieta de eliminación funciona mejor cuando cambias a una proteína nueva que tu perro nunca haya comido — pato, venado o canguro.', 9),
('nutrition', 'Omega-3 fatty acids (from fish oil) can reduce skin inflammation in French Bulldogs. A dose of 20mg EPA+DHA per kg of body weight per day is a common starting point — ask your vet.', 'Los ácidos grasos Omega-3 (del aceite de pescado) pueden reducir la inflamación de la piel en Bulldogs Franceses. Una dosis de 20mg EPA+DHA por kg de peso corporal al día es un punto de partida común — consulta a tu veterinario.', 10),
('nutrition', 'French Bulldogs should eat 2 meals per day at consistent times. Irregular feeding schedules can contribute to digestive stress, which often shows up as skin flare-ups.', 'Los Bulldogs Franceses deben comer 2 veces al día en horarios consistentes. Los horarios de alimentación irregulares pueden contribuir al estrés digestivo, que frecuentemente se manifiesta como brotes en la piel.', 11),
('nutrition', 'Avoid table scraps entirely. Many human foods — onions, grapes, dairy, and heavily seasoned foods — are toxic or inflammatory for Frenchies.', 'Evita los restos de comida de la mesa por completo. Muchos alimentos humanos — cebollas, uvas, lácteos y comidas muy condimentadas — son tóxicos o inflamatorios para los Frenchies.', 12),
('nutrition', 'Look for dog foods with a single protein source and limited ingredients if your Frenchie has skin issues. Multi-protein formulas make it impossible to identify which ingredient causes reactions.', 'Busca alimentos para perros con una sola fuente de proteína e ingredientes limitados si tu Frenchie tiene problemas de piel. Las fórmulas multiproteicas hacen imposible identificar qué ingrediente causa reacciones.', 13),
('nutrition', 'Probiotics designed for dogs may help strengthen gut health, which is directly linked to immune response and skin condition. Ask your vet about a probiotic supplement.', 'Los probióticos diseñados para perros pueden ayudar a fortalecer la salud intestinal, que está directamente relacionada con la respuesta inmune y la condición de la piel. Consulta a tu veterinario sobre un suplemento probiótico.', 14),
('temperature', 'French Bulldogs cannot pant efficiently due to their flat face (brachycephalic anatomy). In temperatures above 25°C (77°F), limit outdoor activity to early morning or evening.', 'Los Bulldogs Franceses no pueden jadear eficientemente debido a su cara plana (anatomía braquicéfala). A temperaturas superiores a 25°C, limita la actividad al aire libre a la mañana temprana o la tarde.', 15),
('temperature', 'Never leave a French Bulldog in a parked car, even with windows cracked. They overheat 3–5x faster than dogs with normal muzzle length.', 'Nunca dejes a un Bulldog Francés en un auto estacionado, ni siquiera con las ventanas entreabiertas. Se sobrecalientan 3–5 veces más rápido que los perros con hocico de longitud normal.', 16),
('temperature', 'Hot pavement burns Frenchie paws fast. The 5-second rule: place your hand on the pavement. If it''s too hot for your hand after 5 seconds, it''s too hot for their paws.', 'El pavimento caliente quema las patas de los Frenchies rápidamente. La regla de los 5 segundos: coloca tu mano en el pavimento. Si está demasiado caliente para tu mano después de 5 segundos, lo está también para sus patas.', 17),
('temperature', 'Cooling mats and elevated beds help Frenchies regulate body temperature indoors. Direct floor contact with hot surfaces increases their heat stress significantly.', 'Las colchonetas refrescantes y las camas elevadas ayudan a los Frenchies a regular su temperatura corporal en interiores. El contacto directo con superficies calientes aumenta significativamente su estrés térmico.', 18),
('temperature', 'In cold weather below 7°C (45°F), French Bulldogs need a dog jacket for walks. Their short coat provides minimal insulation and they lose heat rapidly.', 'En clima frío por debajo de 7°C, los Bulldogs Franceses necesitan una chaqueta para las caminatas. Su pelaje corto proporciona un aislamiento mínimo y pierden calor rápidamente.', 19),
('ears', 'Check your Frenchie''s ears weekly for dark discharge, odor, or excessive scratching at the ear. These are early signs of ear infection (otitis), very common in the breed.', 'Revisa las orejas de tu Frenchie semanalmente en busca de secreción oscura, olor o rascado excesivo en el oído. Estas son señales tempranas de infección del oído (otitis), muy común en la raza.', 20),
('ears', 'Clean ears monthly (or as directed by your vet) with a vet-approved ear cleaner. Never insert cotton swabs into the ear canal — you risk pushing debris deeper.', 'Limpia las orejas mensualmente (o según indicación veterinaria) con un limpiador de oídos aprobado por el veterinario. Nunca insertes hisopos en el canal auditivo — podrías empujar los residuos más adentro.', 21),
('ears', 'Frenchies with upright bat ears trap more airflow than floppy-eared breeds, which actually helps reduce moisture buildup. However, the ear canal itself is still prone to yeast.', 'Los Frenchies con orejas de murciélago erguidas atrapan más flujo de aire que las razas con orejas caídas, lo que en realidad ayuda a reducir la acumulación de humedad. Sin embargo, el canal auditivo sigue siendo propenso a hongos.', 22),
('ears', 'After swimming or bathing, dry your Frenchie''s ears immediately. Moisture in the ear canal creates ideal conditions for yeast and bacterial overgrowth.', 'Después de nadar o bañarse, seca las orejas de tu Frenchie inmediatamente. La humedad en el canal auditivo crea condiciones ideales para el crecimiento excesivo de hongos y bacterias.', 23),
('seasonal_allergies', 'French Bulldogs can develop seasonal allergies to pollen, mold, and grass. Spring and fall are peak seasons — you may notice increased scratching, red paws, or watery eyes.', 'Los Bulldogs Franceses pueden desarrollar alergias estacionales al polen, moho y hierba. La primavera y el otoño son las temporadas pico: puedes notar más rascado, patas rojas u ojos llorosos.', 24),
('seasonal_allergies', 'Wipe your Frenchie''s paws and belly after every outdoor walk during pollen season. Allergens cling to fur and are tracked indoors, where continued exposure prolongs reactions.', 'Limpia las patas y el vientre de tu Frenchie después de cada caminata al aire libre durante la temporada de polen. Los alérgenos se adhieren al pelo y se arrastran al interior, donde la exposición continua prolonga las reacciones.', 25),
('seasonal_allergies', 'Consider air purifiers with HEPA filters for rooms where your Frenchie spends most time. This measurably reduces airborne allergen load for sensitive dogs.', 'Considera purificadores de aire con filtros HEPA para las habitaciones donde tu Frenchie pasa más tiempo. Esto reduce mediblemente la carga de alérgenos en el aire para perros sensibles.', 26),
('seasonal_allergies', 'Grass allergies in Frenchies often cause itchy paws and belly. If your dog constantly licks paws after outdoor time, grass allergens are a prime suspect.', 'Las alergias a la hierba en Frenchies frecuentemente causan picazón en patas y vientre. Si tu perro se lame constantemente las patas después de salir, los alérgenos del pasto son el principal sospechoso.', 27),
('seasonal_allergies', 'Bathing your Frenchie every 2–4 weeks during allergy season (with a hypoallergenic, sulfate-free shampoo) removes environmental allergens from the skin and coat.', 'Bañar a tu Frenchie cada 2–4 semanas durante la temporada de alergias (con un shampoo hipoalergénico sin sulfatos) elimina los alérgenos ambientales de la piel y el pelaje.', 28),
('warning_signs', 'Seek immediate veterinary care if your Frenchie shows: labored breathing, blue-tinged gums, collapse, or is unable to stand. These can indicate a life-threatening emergency.', 'Busca atención veterinaria inmediata si tu Frenchie muestra: respiración dificultosa, encías azuladas, colapso o incapacidad para ponerse de pie. Estas pueden indicar una emergencia que pone en riesgo su vida.', 29),
('warning_signs', 'A skin itch score consistently at 7 or above means your Frenchie is in significant discomfort. This level warrants a veterinary appointment within 1–3 days, not just home management.', 'Una puntuación de picazón de la piel consistentemente en 7 o más significa que tu Frenchie sufre una incomodidad significativa. Este nivel amerita una cita veterinaria dentro de 1–3 días, no solo manejo en casa.', 30),
('warning_signs', 'Hot spots (acute moist dermatitis) appear as raw, weeping skin lesions that spread rapidly. They need prompt veterinary treatment — home remedies alone are rarely sufficient.', 'Los "hot spots" (dermatitis húmeda aguda) aparecen como lesiones cutáneas crudas y supurantes que se propagan rápidamente. Necesitan tratamiento veterinario oportuno — los remedios caseros rara vez son suficientes por sí solos.', 31),
('warning_signs', 'Any facial swelling, hives, or sudden vomiting after eating a new food could indicate anaphylaxis. This is a veterinary emergency — do not wait to see if it resolves on its own.', 'Cualquier hinchazón facial, urticaria o vómitos repentinos después de comer un alimento nuevo podría indicar anafilaxia. Esto es una emergencia veterinaria — no esperes a ver si se resuelve por sí sola.', 32),
('warning_signs', 'Blood in urine, stool, or from the skin, as well as unexplained seizures, extreme lethargy, or sudden behavior changes — all require same-day veterinary evaluation.', 'Sangre en orina, heces o en la piel, así como convulsiones inexplicables, letargo extremo o cambios repentinos de comportamiento — todos requieren evaluación veterinaria el mismo día.', 33),
('post_bath', 'After bathing your Frenchie, dry ALL folds immediately — including facial, tail pocket, and any body folds. A hair dryer on the lowest, coolest setting can reach deep folds.', 'Después de bañar a tu Frenchie, seca TODOS los pliegues inmediatamente — incluidos los faciales, el bolsillo de la cola y cualquier pliegue corporal. Un secador en la configuración más baja y fría puede llegar a los pliegues profundos.', 34),
('post_bath', 'Use a dog shampoo with a neutral pH (6.5–7.5). Human shampoos have a lower pH that strips the dog''s skin acid mantle, increasing susceptibility to infections.', 'Usa un shampoo para perros con pH neutro (6.5–7.5). Los shampoos humanos tienen un pH más bajo que destruye el manto ácido de la piel del perro, aumentando la susceptibilidad a infecciones.', 35),
('post_bath', 'Don''t over-bathe your Frenchie. More than once a week can strip natural skin oils and cause dryness or rebound oiliness. Every 2–4 weeks is ideal for most Frenchies.', 'No bañes a tu Frenchie en exceso. Más de una vez a la semana puede eliminar los aceites naturales de la piel y causar sequedad o exceso de grasa. Cada 2–4 semanas es ideal para la mayoría de los Frenchies.', 36),
('post_bath', 'After drying, apply a small amount of unscented coconut oil or dog-specific moisturizer to dry elbow patches — a common rough spot in the breed due to how Frenchies rest.', 'Después de secar, aplica una pequeña cantidad de aceite de coco sin fragancia o hidratante específico para perros en los codos secos — una zona áspera común en la raza debido a la posición en que descansan los Frenchies.', 37),
('weight_control', 'An ideal French Bulldog weighs 8–14 kg. Every extra kilogram increases joint stress, makes breathing harder (already compromised), and worsens skin fold depth.', 'Un Bulldog Francés ideal pesa 8–14 kg. Cada kilogramo extra aumenta el estrés articular, dificulta la respiración (ya comprometida) y empeora la profundidad de los pliegues cutáneos.', 38),
('weight_control', 'Use a measuring cup for every meal — even small overfeedings add up fast for a 10 kg dog. A daily excess of just 50 kcal can mean 2 kg of weight gain in a year.', 'Usa una taza medidora para cada comida — incluso las sobrealimentaciones pequeñas se acumulan rápidamente para un perro de 10 kg. Un exceso diario de solo 50 kcal puede significar 2 kg de aumento de peso en un año.', 39),
('weight_control', 'Treats should make up no more than 10% of daily caloric intake. Use low-calorie training treats and count them as part of the daily food total, not extras.', 'Las golosinas no deben representar más del 10% de la ingesta calórica diaria. Usa golosinas de bajo calorie para entrenamiento y cuéntalas como parte del total de alimento diario, no como extras.', 40),
('weight_control', 'Regular weight checks (monthly at home, every 6 months at the vet) help catch weight gain early, before it compounds into a bigger health issue.', 'Los controles de peso regulares (mensualmente en casa, cada 6 meses con el veterinario) ayudan a detectar el aumento de peso a tiempo, antes de que se convierta en un problema de salud mayor.', 41),
('fold_cleaning', 'If you notice a persistent brown or red stain (porphyrin staining) under the eyes or around folds, it may indicate chronic tear overflow. A vet can determine if a duct issue is contributing.', 'Si notas una mancha persistente marrón o rojiza (mancha por porfirina) debajo de los ojos o alrededor de los pliegues, puede indicar un desbordamiento crónico de lágrimas. Un veterinario puede determinar si un problema del conducto lacrimal está contribuyendo.', 42),
('nutrition', 'Hydration matters for skin health. Ensure fresh water is always available and consider adding a small amount of low-sodium bone broth to your Frenchie''s water to encourage drinking.', 'La hidratación es importante para la salud de la piel. Asegúrate de que siempre haya agua fresca disponible y considera agregar una pequeña cantidad de caldo de huesos bajo en sodio al agua de tu Frenchie para animarlo a beber.', 43),
('seasonal_allergies', 'Mold allergies spike in autumn when leaves decay. If your Frenchie''s symptoms worsen in October-November, check your yard for damp leaf piles and remove them promptly.', 'Las alergias al moho aumentan en otoño cuando las hojas se descomponen. Si los síntomas de tu Frenchie empeoran en octubre-noviembre, revisa tu jardín en busca de pilas de hojas húmedas y retíralas rápidamente.', 44),
('ears', 'A strong or sweet smell from the ears (often described as corn chips or yeast bread) is a classic sign of yeast overgrowth. Don''t ignore this — yeast ear infections are very painful for dogs.', 'Un olor fuerte o dulce proveniente de los oídos (frecuentemente descrito como palomitas o pan de levadura) es una señal clásica de sobrecrecimiento de hongos. No lo ignores — las infecciones de oído por levaduras son muy dolorosas para los perros.', 45),
('temperature', 'Signs of heatstroke in Frenchies: rapid, labored breathing, drooling excessively, glazed eyes, weakness, or bright red gums. Move to shade, apply cool (not cold) wet towels, and call a vet immediately.', 'Señales de golpe de calor en Frenchies: respiración rápida y laboriosa, babeo excesivo, ojos vidriosos, debilidad o encías de color rojo brillante. Muévelo a la sombra, aplica toallas húmedas frescas (no frías) y llama a un veterinario de inmediato.', 46),
('post_bath', 'Check between paw pads for moisture, debris, or interdigital cysts after every bath and outdoor walk. Frenchies are prone to paw fold infections, especially in humid climates.', 'Revisa entre las almohadillas de las patas en busca de humedad, suciedad o quistes interdigitales después de cada baño y caminata al aire libre. Los Frenchies son propensos a infecciones en los pliegues de las patas, especialmente en climas húmedos.', 47),
('warning_signs', 'Excessive paw licking that creates pink/rust staining on the fur is a sign of chronic irritation — often allergic in origin. This deserves veterinary evaluation, not just bandaging.', 'El lamido excesivo de patas que crea manchas rosadas o rojizas en el pelaje es una señal de irritación crónica — frecuentemente de origen alérgico. Esto merece evaluación veterinaria, no solo vendaje.', 48),
('nutrition', 'Zinc deficiency can cause skin scaling and poor coat quality in dogs. If your Frenchie''s coat looks dull or skin is flaking, ask your vet about zinc levels before supplementing on your own.', 'La deficiencia de zinc puede causar descamación de la piel y mala calidad del pelaje en los perros. Si el pelaje de tu Frenchie se ve opaco o la piel se descama, consulta a tu veterinario sobre los niveles de zinc antes de suplementar por tu cuenta.', 49),
('fold_cleaning', 'Consider adding fold cleaning to a specific daily routine (like right after dinner) so it becomes a habit — for both you and your Frenchie. Consistency is the most powerful tool against skin fold dermatitis.', 'Considera incorporar la limpieza de pliegues a una rutina diaria específica (como justo después de cenar) para que se convierta en un hábito — tanto para ti como para tu Frenchie. La consistencia es la herramienta más poderosa contra la dermatitis de pliegues cutáneos.', 50);
